import openapiTS, { astToString } from "openapi-typescript";
import spec from "./openapi.billing.json";

export const BILLING_TYPES_SCRIPT = "bun run billing:types";

const HEADER = `/**
 * GENERATED by \`${BILLING_TYPES_SCRIPT}\` from convex/lib/billing/openapi.billing.json. Do not edit.
 * Update the spec copy and contract.json together, then regenerate.
 */

`;

export async function generateBillingTypes(): Promise<string> {
  return HEADER + astToString(await openapiTS(spec as unknown as Parameters<typeof openapiTS>[0]));
}
